function hToPh(H){ return -Math.log(H)/Math.LN10; }
function phToH(pH){ return Math.pow(10,-pH); }
function pohToPh(pOH){ return 14-pOH; }
function phToPoh(pH){ return 14-pH; }
function strongAcidPh(C){ return -Math.log(C)/Math.LN10; } // 一元强酸
function weakAcidH(C,Ka){ return Math.sqrt(Ka*C); }
function weakAcidPh(C,Ka){ return hToPh(Math.sqrt(Ka*C)); }
var EXPORTS={hToPh:hToPh, phToH:phToH, pohToPh:pohToPh, phToPoh:phToPoh, strongAcidPh:strongAcidPh, weakAcidPh:weakAcidPh, weakAcidH:weakAcidH};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PhForgePure = EXPORTS; }
